<!doctype html><html><head><meta charset="utf-8"><title>Tiket {{ $ticket->ticket_code }}</title><style>body{font-family:Arial,sans-serif;color:#142d4e;padding:35px}.box{border:2px solid #3867ff;border-radius:16px;padding:25px;max-width:720px;margin:auto}.bar{background:#3867ff;color:#fff;padding:14px;border-radius:10px}.grid{display:grid;grid-template-columns:1fr 1fr;gap:18px;margin-top:25px}.qr{text-align:center;border-top:1px dashed #aaa;margin-top:20px;padding-top:20px}.qr img{width:220px;height:220px}@media print{body{padding:0}button{display:none}}</style></head><body><div class="box"><div class="bar">EVENTKU · DIGITAL TICKET · {{ $ticket->status }}</div><h1>{{ $ticket->registration->event->name }}</h1><p>{{ $ticket->registration->event->start_at->format('d M Y, H:i') }} WIB · {{ $ticket->registration->event->location }}</p><div class="grid"><div><b>Peserta</b><br>{{ $ticket->registration->user->name }}<br><br><b>Jenis Tiket</b><br>{{ $ticket->registration->ticketType->name }}</div><div><b>Kode Tiket</b><br>{{ $ticket->ticket_code }}<br><br><b>Kode Registrasi</b><br>{{ $ticket->registration->registration_code }}</div></div><div class="qr"><img src="{{ route('participant.ticket.qr',$ticket) }}"><p>Tunjukkan QR ini di gate. Tiket ini hanya dapat digunakan satu kali.</p></div><button onclick="window.print()">Cetak / Simpan PDF</button></div></body></html>
